/**
 * The question that had no answer at all, from the Greenhouse form that died
 * on it (2026-08-21). "Your country" and "the country this role is based in"
 * are different questions, and answering the first with the second's careful
 * negative would have been a false negative — the candidate may certainly work
 * where they live.
 */
describe("authorization in the candidate's own country", () => {
  it.each([
    "Do you have authorization to live and work in your country?*",
    "Are you legally authorized to work in your country of residence?",
    "Você tem autorização para trabalhar no seu país?",
    "¿Tienes autorización para trabajar en tu país?",
  ])("answers yes to %j", (q) => {
    const a = conservativeDefaultAnswer(q);
    expect(a?.kind).toBe("boolean");
    expect(a?.answer).toMatch(/^Yes/);
  });

  it("still answers no for the United States", () => {
    const a = conservativeDefaultAnswer(
      "Are you legally authorized to work in the United States?",
    );
    expect(a?.answer).toMatch(/^No/);
  });
});

